@startuml

abstract class Person {
  + FirstName : string
  + LastName : string
}

class Teacher extends Person {
  + Email : string
}

class Student extends Person {
}

class School {
  + Name : string
}

class TeachingAssignment {
  + Hours : int
}

class ClassGroup {
  + Name : string
}

class ClassRoom {
  + Name : string
  + Capacity : int
}

class OtherRoom {
  + Name : string
  + Size : double
}

Teacher "1 Principal" -- "0..1" School
Teacher "1" -- "0..3" TeachingAssignment
TeachingAssignment "*" -- "1" School
Teacher "1" -- "*" TeachingAssignment
Student "*" -- "1" School
Student "*" -- "1" ClassGroup
ClassGroup "1" -- "1" ClassRoom
School "1" -- "*" OtherRoom

@enduml

